export function inferMetadata(name, county) {
  const n = name.toLowerCase();
  if (n.includes('lake') || n.includes('pond')) return { species: ['Rainbow Trout', 'Largemouth Bass'], type: 'lake' };
  if (n.includes('river') || n.includes('creek') || n.includes('fork') || n.includes('dam')) return { species: ['Steelhead', 'Trout', 'Salmon'], type: 'river' };
  if (n.includes('bay') || n.includes('harbor') || n.includes('cove') || n.includes('sound')) return { species: ['Salmon', 'Lingcod', 'Rockfish'], type: 'saltwater' };
  if (n.includes('reservoir') || n.includes('bar')) return { species: ['Walleye', 'Bass', 'Rainbow Trout'], type: 'reservoir' };
  return { species: ['Trout', 'Bass'], type: 'access' };
}

export function enrichSite(site) {
  const meta = SITE_METADATA[site.name] || inferMetadata(site.name, site.county);
  return { ...site, ...meta, isCurated: !!SITE_METADATA[site.name] };
}

export const SITES = SITES_RAW.map(enrichSite);

